import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from './Navbar';

const Profile = () => {
  const [user, setUser] = useState(JSON.parse(localStorage.getItem('user') || '{}'));
  const [myPosts, setMyPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newPost, setNewPost] = useState({
    caption: '',
    image: '',
    area: ''
  });
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    fetchMyPosts();
  }, []);

  const fetchMyPosts = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:5000/api/posts', {
        headers: { 'Authorization': `Bearer ${token}` }
      });

      if (response.data.success) {
        // Filter posts by current user
        const userPosts = response.data.posts.filter(
          post => post.author._id === user._id
        );
        setMyPosts(userPosts);
      }
    } catch (err) {
      console.error('Fetch posts error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleCreatePost = async (e) => {
    e.preventDefault();
    
    if (!newPost.caption || !newPost.image || !newPost.area) {
      alert('Please fill in all fields');
      return;
    }

    setCreating(true);
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:5000/api/posts',
        newPost,
        {
          headers: { 'Authorization': `Bearer ${token}` }
        }
      );

      if (response.data.success) {
        alert(`Post created successfully! ${response.data.notificationsSent} users notified.`);
        setShowCreateModal(false);
        setNewPost({ caption: '', image: '', area: '' });
        fetchMyPosts(); // Refresh posts
      }
    } catch (err) {
      console.error('Create post error:', err);
      alert(err.response?.data?.message || 'Failed to create post');
    } finally {
      setCreating(false);
    }
  };

  const calculateAuthenticity = (post) => {
    const totalVotes = (post.verifications?.length || 0) + (post.refutations?.length || 0);
    return totalVotes > 0 
      ? Math.round((post.verifications?.length || 0) / totalVotes * 100) 
      : 50;
  };

  return (
    <div className="min-h-screen bg-gray-100">
      <Navbar />
      
      <div className="max-w-4xl mx-auto px-4 py-8">
        {/* Profile Header */}
        <div className="bg-white rounded-lg shadow-md p-6 mb-6">
          <div className="flex justify-between items-start">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">
                {user.fullName || 'User Profile'}
              </h1>
              <div className="space-y-1 text-gray-600">
                <p>📧 {user.email}</p>
                <p>📱 {user.phoneNumber}</p>
                <p>📍 {user.district}, {user.upazila}</p>
                <p>🏠 {user.address}</p>
                <p>🆔 NID: {user.nidNumber}</p>
                <p className="font-semibold text-blue-600">
                  Role: {user.role || 'User'}
                </p>
              </div>
            </div>
            
            <button
              onClick={() => setShowCreateModal(true)}
              className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-6 rounded-lg transition-colors shadow-md"
            >
              + Create New Post
            </button>
          </div>
        </div>

        {/* My Posts Section */}
        <div className="bg-white rounded-lg shadow-md p-6">
          <h2 className="text-2xl font-bold text-gray-900 mb-4">
            My Posts ({myPosts.length})
          </h2>

          {loading ? (
            <div className="text-center py-8">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
              <p className="mt-4 text-gray-600">Loading your posts...</p>
            </div>
          ) : myPosts.length === 0 ? (
            <div className="text-center py-12">
              <p className="text-gray-600 text-lg">You haven't created any posts yet</p>
              <button
                onClick={() => setShowCreateModal(true)}
                className="mt-4 bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg transition-colors"
              >
                Create Your First Post
              </button>
            </div>
          ) : (
            <div className="space-y-4">
              {myPosts.map(post => (
                <div key={post._id} className="border border-gray-200 rounded-lg p-4 hover:shadow-md transition-shadow">
                  <div className="flex gap-4">
                    {post.image && (
                      <img 
                        src={post.image} 
                        alt="Post" 
                        className="w-24 h-24 object-cover rounded-lg"
                        onError={(e) => {
                          e.target.src = 'https://via.placeholder.com/150?text=No+Image';
                        }}
                      />
                    )}
                    <div className="flex-1">
                      <p className="text-gray-800 font-medium mb-2">{post.caption}</p>
                      <div className="text-sm text-gray-600 space-y-1">
                        <p>📍 Area: {post.area}</p>
                        <p>📅 {new Date(post.createdAt).toLocaleString()}</p>
                        <div className="flex gap-4 mt-2">
                          <span className="text-green-600 font-semibold">
                            ✅ {post.verifications?.length || 0} Verified
                          </span>
                          <span className="text-red-600 font-semibold">
                            ❌ {post.refutations?.length || 0} Refuted
                          </span>
                          <span className="text-blue-600 font-semibold">
                            Authenticity: {calculateAuthenticity(post)}%
                          </span>
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Create Post Modal */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-lg w-full p-6">
            <h2 className="text-2xl font-bold mb-4">Report New Incident</h2>
            
            <form onSubmit={handleCreatePost}>
              <div className="mb-4">
                <label className="block text-gray-700 font-semibold mb-2">
                  Caption *
                </label>
                <textarea
                  value={newPost.caption}
                  onChange={(e) => setNewPost({ ...newPost, caption: e.target.value })}
                  placeholder="Describe the incident..."
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  rows="4"
                  maxLength="500"
                  required
                />
                <p className="text-xs text-gray-500 mt-1">
                  {newPost.caption.length}/500 characters
                </p>
              </div>

              <div className="mb-4">
                <label className="block text-gray-700 font-semibold mb-2">
                  Image URL *
                </label>
                <input
                  type="url"
                  value={newPost.image}
                  onChange={(e) => setNewPost({ ...newPost, image: e.target.value })}
                  placeholder="https://example.com/image.jpg"
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
                <p className="text-xs text-gray-500 mt-1">
                  Provide a direct link to the incident image
                </p>
              </div>

              <div className="mb-6">
                <label className="block text-gray-700 font-semibold mb-2">
                  Area *
                </label>
                <input
                  type="text"
                  value={newPost.area}
                  onChange={(e) => setNewPost({ ...newPost, area: e.target.value })}
                  placeholder="e.g., Dhanmondi, Gulshan, etc."
                  className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  required
                />
                <p className="text-xs text-gray-500 mt-1">
                  Users in this area will be notified
                </p>
              </div>

              <div className="flex gap-3">
                <button
                  type="submit"
                  disabled={creating}
                  className="flex-1 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 text-white font-semibold py-3 px-4 rounded-lg transition-colors"
                >
                  {creating ? 'Creating...' : 'Create Post'}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowCreateModal(false);
                    setNewPost({ caption: '', image: '', area: '' });
                  }}
                  className="flex-1 bg-gray-200 hover:bg-gray-300 text-gray-800 font-semibold py-3 px-4 rounded-lg transition-colors"
                >
                  Cancel
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Profile;
